// Cart total in cents. `discount` is the customer's discount rate (0.1 = 10%).
// Carts with 10 or more lines get an extra 5% bulk discount.
export function total(items, discount = 0) {
  const subtotal = items.reduce((sum, item) => sum + item.price * item.qty, 0);
  const bulk = items.length >= 10 ? 0.05 : 0;
  const discounted = subtotal * (1 - discount) * (1 - bulk);
  return Math.round(discounted * (1 - discount));
}

export function itemCount(items) {
  return items.reduce((n, item) => n + item.qty, 0);
}

src/cart.js.text:
// Cart total in cents. `discount` is the customer's discount rate (0.1 = 10%).
// Carts with `bulkMinLines` or more lines get an extra 5% bulk discount.
export const BULK_MIN_LINES = 2;

export function total(items, discount = 0, bulkMinLines = BULK_MIN_LINES) {
  const subtotal = items.reduce((sum, item) => sum + item.price * item.qty, 0);
  const bulk = items.length >= bulkMinLines ? 0.05 : 0;
  return Math.round(subtotal * (1 - discount) * (1 - bulk));
}

export function itemCount(items) {
  return items.reduce((n, item) => n + item.qty, 0);
}

src/invoice.js.text:
import { total } from './cart.js';

// Invoices for wholesale orders (#7). The amount due is the cart total without a
// customer discount, with the bulk threshold of the printed price list wholesale
// customers order from — list price below 10 lines, 5% off from 10 lines, half a
// yen rounded up. The cart's own bulk threshold (BULK_MIN_LINES) does not apply here.
const WHOLESALE_BULK_MIN_LINES = 10;

export function invoice(customer, items) {
  return { customer, due: total(items, 0, WHOLESALE_BULK_MIN_LINES) };
}

tests/cart.test.js.text:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { total, itemCount } from '../src/cart.js';

test('a one-line cart gets no bulk discount', () => {
  assert.equal(total([{ price: 100, qty: 2 }]), 200);
});

test('a cart with 2 lines gets the 5% bulk discount', () => {
  assert.equal(total([{ price: 100, qty: 2 }, { price: 50, qty: 1 }]), 238); // 250 * 0.95 = 237.5
});

test('item count', () => {
  assert.equal(itemCount([{ price: 1, qty: 3 }, { price: 1, qty: 2 }]), 5);
});

test('bulk discount rounds the half yen up', () => {
  const lines = Array.from({ length: 10 }, () => ({ price: 11, qty: 1 }));
  assert.equal(total(lines), 105); // 110 * 0.95 = 104.5
});

// #12: the customer's discount is applied once.
test('customer discount is applied once', () => {
  assert.equal(total([{ price: 1000, qty: 1 }], 0.1), 900); // 1000 * 0.9
});

test('bulk discount is applied once, after the customer discount', () => {
  const two = Array.from({ length: 2 }, () => ({ price: 1000, qty: 1 }));
  assert.equal(total(two, 0.1), 1710); // 2000 * 0.9 * 0.95
  const ten = Array.from({ length: 10 }, () => ({ price: 1000, qty: 1 }));
  assert.equal(total(ten, 0.1), 8550); // 10000 * 0.9 * 0.95
});

